import sys, os; sys.path.insert(0, os.path.dirname(os.path.dirname(__file__)))
from dsl import *
U("s6-u03")
C = "B1-B2"

L(1, "Partes de um artigo", "kop, intro, tussenkop, citaat",
  ["Reconhecer a estrutura de um artigo jornalístico"],
  vocab=[V("v-kop-artikel","kop","título (de artigo)","noun","de"), V("v-tussenkop","tussenkop","intertítulo","noun","de"),
         V("v-citaat","citaat","citação","noun","het"), V("v-lezer","lezer","leitor","noun","de"),
         V("v-samenvatting","samenvatting","resumo","noun","de")],
  ex=[("De kop moet de aandacht trekken.","O título deve chamar a atenção."),("De intro vat het artikel samen.","A introdução resume o artigo."),("Het citaat komt van een expert.","A citação é de um especialista."),("Tussenkoppen helpen de lezer.","Os intertítulos ajudam o leitor.")],
  gram=[G("g-artikel-structuur","Pirâmide invertida","Num artigo de notícia, o mais importante vem **primeiro**: **kop** (título) → **intro/lead** (quem, o quê, onde, quando) → pormenores e **citaten** → contexto. Por isso, ler o título e o primeiro parágrafo dá logo a ideia principal.",
    [("«We zijn heel blij met het resultaat,» aldus de burgemeester.","«Estamos muito contentes com o resultado», disse o presidente da câmara.")],
    "«aldus» = segundo/disse (usado depois de citações).")],
  review=["v-artikel","v-krantenkop","v-bron"],
  cefr=C, exs=[
    MA([("kop","título"),("tussenkop","intertítulo"),("citaat","citação"),("lezer","leitor"),("samenvatting","resumo")], "Artigo.", ["v-kop-artikel","v-tussenkop","v-citaat","v-lezer","v-samenvatting"]),
    AR("citaat","a citação","het", "Het citaat.", ["v-citaat"]),
    TR("nl-pt","De intro vat het artikel samen.", ["A introdução resume o artigo"], "samenvatten.", ["v-samenvatting"]),
    TR("pt-nl","O título deve chamar a atenção.", ["De kop moet de aandacht trekken"], "de aandacht trekken.", ["v-kop-artikel"]),
    MC("Onde encontra mais depressa a informação principal de uma notícia?", ["*No título e no primeiro parágrafo","No último parágrafo|Normalmente é contexto.","Nas fotos|Não necessariamente."], "Pirâmide invertida.", ["v-kop-artikel"]),
    MC("«…, aldus de minister.» — «aldus» significa…", ["*disse/segundo (depois de uma citação)","portanto|Não aqui.","contra|Não."], "aldus.", ["v-citaat"]),
    FE(["De","citaat","komt","van","een","expert."], 0, "Het", "Citaat é het-woord: het citaat.", ["v-citaat"]),
    LI("«We zijn heel blij met het resultaat,» aldus de burgemeester.", ["We zijn heel blij met het resultaat(,) aldus de burgemeester"], "«Estamos muito contentes com o resultado», disse o presidente da câmara.", "aldus.", ["v-citaat"]),
    FB("Schrijf een korte ___ van de tekst in drie zinnen.", ["samenvatting"], "Resumo.", ["v-samenvatting"], choices=["samenvatting","kop","citaat"], tr="Escreve um resumo curto do texto em três frases."),
    WO("Os intertítulos ajudam o leitor.", ["Tussenkoppen","helpen","de","lezer"], "Simples.", ["v-tussenkop","v-lezer"]),
  ], diff=5, mins=7)

L(2, "Encontrar a ideia principal", "De kern van de tekst. Waar gaat het over?",
  ["Identificar a ideia principal e distingui-la de pormenores"],
  vocab=[V("v-kern","kern","essência|cerne","noun","de"), V("v-bijzaak","bijzaak","pormenor secundário","noun","de"),
         V("v-hoofdzaak","hoofdzaak","o essencial","noun","de"), V("v-strekking","strekking","sentido geral","noun","de")],
  ex=[("Wat is de kern van het artikel?","Qual é o cerne do artigo?"),("Dat is een bijzaak.","Isso é um pormenor secundário."),("Hoofdzaken en bijzaken onderscheiden.","Distinguir o essencial do acessório."),("De strekking van de tekst is positief.","O sentido geral do texto é positivo.")],
  review=["v-hoofdgedachte","v-samenvatting","v-kernzin"],
  cefr=C, exs=[
    MA([("kern","cerne"),("bijzaak","pormenor"),("hoofdzaak","essencial"),("strekking","sentido geral")], "Ideia principal.", ["v-kern","v-bijzaak","v-hoofdzaak","v-strekking"]),
    CO("text","Minder vlees, meer bonen", "Nederlanders eten steeds minder vlees. Volgens het Voedingscentrum daalde de vleesconsumptie de afgelopen tien jaar met ongeveer tien procent. Vooral jongeren kiezen vaker voor vegetarische maaltijden. Supermarkten spelen daarop in: het aanbod van vleesvervangers is sterk gegroeid. Toch blijft Nederland in Europa een van de grotere vleeseters. Volgens experts is er dus nog werk aan de winkel.",
       [("Qual é a ideia principal?", ["*Os neerlandeses comem menos carne, mas ainda comem bastante","Os supermercados vendem mais feijão","Os jovens não gostam de carne"]),("Qual destas é um pormenor (bijzaak)?", ["*O aumento da oferta de substitutos de carne nos supermercados","A diminuição do consumo de carne","Ainda há trabalho a fazer"])],
       "werk aan de winkel = trabalho por fazer.", ["v-kern","v-bijzaak"]),
    TR("pt-nl","Qual é o cerne do artigo?", ["Wat is de kern van het artikel"], "de kern.", ["v-kern"]),
    TR("nl-pt","Dat is een bijzaak.", ["Isso é um pormenor secundário","Isso é secundário","Isso é um pormenor"], "bijzaak.", ["v-bijzaak"]),
    MC("Para encontrar a ideia principal, é útil…", ["*ler o título, a introdução e as primeiras frases de cada parágrafo","ler só os números|Não.","ler só o último parágrafo|Insuficiente."], "Estratégia.", ["v-kern"]),
    MC("«Er is nog werk aan de winkel» significa…", ["*Ainda há muito por fazer","Há vagas na loja|Literal.","A loja está fechada|Não."], "Expressão.", []),
    AR("strekking","o sentido geral","de", "-ing → de.", ["v-strekking"]),
    FE(["Wat","is","het","kern","van","de","tekst?"], 2, "de", "Kern é de-woord: de kern.", ["v-kern"]),
    LI("Laten we ons op de hoofdzaken concentreren.", ["Laten we ons op de hoofdzaken concentreren"], "Concentremo-nos no essencial.", "hoofdzaken.", ["v-hoofdzaak"]),
    SW("Resuma o texto «Minder vlees, meer bonen» numa só frase com a ideia principal.", ["Nederlanders eten minder vlees dan vroeger, maar ze eten nog steeds relatief veel."], ["Uma frase", "Ideia principal (não pormenores)", "Contraste com **maar**"], 10, "Ideia principal.", ["v-kern","v-hoofdzaak"]),
  ], diff=5, mins=7)

L(3, "Facto, opinião e intenção do autor", "Wil de schrijver informeren, overtuigen of amuseren?",
  ["Distinguir factos de opiniões e reconhecer a intenção do texto"],
  vocab=[V("v-feit","feit","facto","noun","het","feiten"), V("v-informeren","informeren","informar","verb"),
         V("v-schrijfdoel","schrijfdoel","objetivo do texto","noun","het"), V("v-objectief","objectief","objetivo (imparcial)","adjective"),
         V("v-subjectief","subjectief","subjetivo","adjective")],
  ex=[("Dat is een feit, geen mening.","Isso é um facto, não uma opinião."),("Het artikel wil vooral informeren.","O artigo quer sobretudo informar."),("Wat is het schrijfdoel?","Qual é o objetivo do texto?"),("Een column is subjectief.","Uma crónica é subjetiva.")],
  gram=[G("g-schrijfdoel","Objetivos de um texto","**informeren** (notícia, folheto), **overtuigen** (opinião, publicidade), **amuseren** (crónica humorística), **activeren** (instruções, apelos: *Meld je nu aan!*). Sinais de opinião: *ik vind, helaas, gelukkig, natuurlijk, moeten, beste, schandalig*.",
    [("Gelukkig kiezen steeds meer mensen voor de fiets.","Felizmente cada vez mais pessoas escolhem a bicicleta. (opinião)")])],
  review=["v-mening","v-overtuigen","v-bron"],
  cefr=C, exs=[
    MA([("feit","facto"),("informeren","informar"),("schrijfdoel","objetivo do texto"),("objectief","imparcial"),("subjectief","subjetivo")], "Textos.", ["v-feit","v-informeren","v-schrijfdoel","v-objectief","v-subjectief"]),
    MC("«Amsterdam heeft ongeveer 900.000 inwoners.» É…", ["*een feit","een mening|É verificável.","een advertentie|Não."], "Facto.", ["v-feit"]),
    MC("«Amsterdam is de mooiste stad van Europa.» É…", ["*een mening","een feit|Não é verificável.","een citaat|Não necessariamente."], "Opinião.", ["v-subjectief"]),
    MC("Qual palavra revela opinião?", ["*schandalig","gisteren|Neutra.","tachtig|Neutra."], "Palavra avaliativa.", ["v-subjectief"]),
    MC("Um folheto «Meld je nu aan voor de cursus!» quer…", ["*activeren (levar a agir)","amuseren|Não.","alleen informeren|Pede uma ação."], "Objetivo.", ["v-schrijfdoel"]),
    AR("feit","o facto","het", "Het feit.", ["v-feit"]),
    TR("pt-nl","Isso é um facto, não uma opinião.", ["Dat is een feit(,) geen mening"], "feit/mening.", ["v-feit"]),
    TR("nl-pt","Een column is subjectief.", ["Uma crónica é subjetiva","Uma coluna de opinião é subjetiva"], "column.", ["v-subjectief"]),
    FE(["Dit","is","een","objectieve","feit."], 3, "objectief", "het feit → een objectief feit.", ["v-objectief"]),
    LI("De schrijver wil de lezer vooral overtuigen.", ["De schrijver wil de lezer vooral overtuigen"], "O autor quer sobretudo convencer o leitor.", "schrijfdoel.", ["v-schrijfdoel"]),
  ], diff=5, mins=7)

L(4, "Vocabulário de textos informativos", "aantal, toename, afname, gevolg, oorzaak",
  ["Dominar palavras frequentes em textos informativos"],
  vocab=[V("v-toename","toename","aumento","noun","de"), V("v-afname","afname","diminuição","noun","de"),
         V("v-oorzaak","oorzaak","causa","noun","de"), V("v-gevolg","gevolg","consequência","noun","het","gevolgen"),
         V("v-aantal","aantal","número (quantidade)","noun","het")],
  ex=[("Er is een toename van het aantal fietsers.","Há um aumento do número de ciclistas."),("De afname komt door de hoge prijzen.","A diminuição deve-se aos preços altos."),("Wat is de oorzaak?","Qual é a causa?"),("Dat heeft grote gevolgen.","Isso tem grandes consequências.")],
  gram=[G("g-aantal-enkelvoud","Het aantal + verbo","**Het aantal** (o número de) leva o verbo no **singular**: *Het aantal fietsers **stijgt**.* Mas **een aantal** (alguns) leva normalmente plural: *Een aantal mensen **zijn** ziek.* Oorzaak → **door/doordat**; gevolg → **daardoor/dus**.",
    [("Het aantal toeristen is gestegen.","O número de turistas subiu.")])],
  review=["v-stijgen","v-dalen","v-door","v-daardoor"],
  cefr=C, exs=[
    MA([("toename","aumento"),("afname","diminuição"),("oorzaak","causa"),("gevolg","consequência"),("aantal","número")], "Textos informativos.", ["v-toename","v-afname","v-oorzaak","v-gevolg","v-aantal"]),
    FB("Het aantal fietsers ___ elk jaar.", ["stijgt"], "het aantal → singular.", ["v-aantal"], choices=["stijgt","stijgen","gestegen"], tr="O número de ciclistas sobe todos os anos."),
    TR("pt-nl","Qual é a causa?", ["Wat is de oorzaak"], "de oorzaak.", ["v-oorzaak"]),
    TR("pt-nl","Isso tem grandes consequências.", ["Dat heeft grote gevolgen"], "gevolgen.", ["v-gevolg"]),
    TR("nl-pt","Er is een toename van het aantal fietsers.", ["Há um aumento do número de ciclistas"], "toename.", ["v-toename"]),
    AR("gevolg","a consequência","het", "Het gevolg.", ["v-gevolg"]),
    AR("aantal","o número","het", "Het aantal.", ["v-aantal"]),
    FE(["Het","aantal","toeristen","zijn","gestegen."], 3, "is", "het aantal → singular: is.", ["v-aantal"]),
    MC("O oposto de «toename» é…", ["*afname","oorzaak|Causa.","gevolg|Consequência."], "Antónimos.", ["v-afname"]),
    LI("De oorzaak van de afname is nog onduidelijk.", ["De oorzaak van de afname is nog onduidelijk"], "A causa da diminuição ainda não é clara.", "oorzaak/afname.", ["v-oorzaak","v-afname"]),
  ], diff=5, mins=7)

L(5, "Ler um artigo completo", "Um artigo sobre trabalho remoto.",
  ["Ler um artigo e responder a perguntas de compreensão variadas"],
  vocab=[V("v-ontwikkeling","ontwikkeling","evolução|desenvolvimento","noun","de"), V("v-werkgever-verwacht","verwachting","expectativa","noun","de"),
         V("v-hybride","hybride","híbrido","adjective"), V("v-eenzaamheid","eenzaamheid","solidão","noun","de")],
  ex=[("Hybride werken is de nieuwe norm.","O trabalho híbrido é a nova norma."),("Die ontwikkeling begon tijdens corona.","Essa evolução começou durante a covid."),("De verwachtingen zijn hoog.","As expectativas são altas."),("Eenzaamheid is een risico.","A solidão é um risco.")],
  review=["v-thuiswerken","v-productiviteit","v-toename","v-gevolg"],
  cefr=C, exs=[
    MA([("ontwikkeling","evolução"),("verwachting","expectativa"),("hybride","híbrido"),("eenzaamheid","solidão")], "Artigo.", ["v-ontwikkeling","v-werkgever-verwacht","v-hybride","v-eenzaamheid"]),
    CO("text","Thuiswerken blijft, maar anders", "Sinds de coronacrisis werken veel meer Nederlanders (deels) thuis. Volgens het CBS werkte in 2023 bijna de helft van de werkenden weleens thuis. Toch zien we een nieuwe ontwikkeling: steeds meer werkgevers vragen hun personeel om vaker naar kantoor te komen.\n\nWaarom? Werkgevers noemen vooral de samenwerking. 'Nieuwe collega's leren veel door gewoon naast ervaren mensen te zitten,' zegt HR-directeur Ingrid Bos. Ook eenzaamheid speelt een rol: vooral jongeren missen het contact.\n\nWerknemers zijn niet altijd enthousiast. Zij noemen de reistijd en de rust thuis als grote voordelen. De meeste bedrijven kiezen daarom voor een hybride model: twee of drie dagen op kantoor, de rest thuis.",
       [("Qual é a nova evolução descrita?", ["*Empregadores pedem mais presença no escritório","Todos passam a trabalhar em casa","Fecham-se escritórios"]),("Porque querem os empregadores mais presença?", ["*Colaboração e aprendizagem dos novos colegas","Para poupar dinheiro","Por causa do trânsito"]),("Qual é a solução mais comum?", ["*Um modelo híbrido","Teletrabalho total","Escritório cinco dias"]),("Qual é o objetivo principal do texto?", ["*Informar","Convencer a trabalhar em casa","Divertir"])],
       "Repare na estrutura: situação → mudança → razões → reação → solução.", ["v-ontwikkeling","v-hybride","v-eenzaamheid"]),
    TR("pt-nl","O trabalho híbrido é a nova norma.", ["Hybride werken is de nieuwe norm","Hybride werken is de nieuwe standaard"], "hybride.", ["v-hybride"]),
    TR("nl-pt","Eenzaamheid is een risico.", ["A solidão é um risco"], "eenzaamheid.", ["v-eenzaamheid"]),
    AR("verwachting","a expectativa","de", "-ing → de.", ["v-werkgever-verwacht"]),
    MC("No texto, a citação de Ingrid Bos serve para…", ["*ilustrar o argumento dos empregadores","dar a opinião dos trabalhadores|Ela é diretora de RH.","mostrar números|É uma citação."], "Função da citação.", ["v-citaat"]),
    FE(["Steeds","meer","werkgevers","vraagt","hun","personeel","om","te","komen."], 3, "vragen", "Sujeito plural: vragen.", []),
    LI("De meeste bedrijven kiezen voor een hybride model.", ["De meeste bedrijven kiezen voor een hybride model"], "A maioria das empresas opta por um modelo híbrido.", "kiezen voor.", ["v-hybride"]),
    FB("Deze ___ begon al voor corona.", ["ontwikkeling"], "Evolução.", ["v-ontwikkeling"], choices=["ontwikkeling","eenzaamheid","verwachting"], tr="Esta evolução começou já antes da covid."),
    SW("Resuma o artigo em 2–3 frases com as suas palavras.", ["Na corona werken veel Nederlanders deels thuis. Werkgevers willen nu dat mensen vaker naar kantoor komen, vooral voor de samenwerking. De meeste bedrijven kiezen voor een hybride model."], ["Situação", "Mudança e razão", "Solução", "Palavras próprias"], 30, "Resumo.", ["v-samenvatting"]),
  ], diff=5, mins=8)

W()
